  Definition REGF (R : bvmap 5 word) : Prop :=
    getr R 2%bv = Z_to_bv 64 S1 /\ getr R 3%bv = gp /\ getr R 4%bv = tp /\ getr R 8%bv = s0w /\ getr R 9%bv = Z_to_bv 64 S1
    /\ getr R 18%bv = Z_to_bv 64 SHBASE /\ getr R 19%bv = Z_to_bv 64 p /\ getr R 20%bv = s4w /\ getr R 21%bv = s5w /\ getr R 22%bv = s6w
    /\ getr R 23%bv = Z_to_bv 64 (obj + 8) /\ getr R 24%bv = t0w /\ getr R 25%bv = s9w /\ getr R 26%bv = Z_to_bv 64 n
    /\ getr R 27%bv = Z_to_bv 64 (8 * n).
  Definition REGX (R : bvmap 5 word) : Prop :=
    getr R 2%bv = Z_to_bv 64 S1 /\ getr R 3%bv = gp /\ getr R 4%bv = tp /\ getr R 5%bv = t0w /\ getr R 8%bv = s0w /\ getr R 9%bv = Z_to_bv 64 S1
    /\ getr R 18%bv = Z_to_bv 64 SHBASE /\ getr R 19%bv = Z_to_bv 64 p /\ getr R 20%bv = s4w /\ getr R 22%bv = s6w
    /\ getr R 23%bv = Z_to_bv 64 (obj + 8) /\ getr R 24%bv = Z_to_bv 64 (obj + 8) /\ getr R 25%bv = s9w /\ getr R 26%bv = Z_to_bv 64 n
    /\ getr R 27%bv = s5w.

  Lemma loop_all : forall R, REGF R ->
    cell8 ASEGS ML sent (hdaddr ents) -> chain ASEGS ML ents -> (forall e, In e ents -> cell8 ASEGS ML (addr e + 8) (hkey e)) ->
    cell8 ASEGS ML obj p -> (forall i, 0 <= i < n -> cell8 ASEGS ML (p + 8 * i) 0) ->
    addressable ML p (8 * n) -> addressable ML obj 40 -> (forall e, In e ents -> addressable ML (addr e) 32) ->
    mem_inv asegs ML -> wr_at asegs ML p (8 * n) -> wr_at asegs ML obj 40 -> (forall e, In e ents -> wr_at asegs ML (addr e) 32) ->
    exists R' M', CatSim.msteps asegs (st R R_MS ML) (st R' R_EXIT M') /\ REGX R'
      /\ ((ents = [] /\ M' = ML) \/ (exists P' Bf' Rl, LSTA P' [] Bf' M' Rl)).
Proof.
